css:
/* Team directory: filter chips (Executive Staff + every location), a live count, and one
   section per team. Without JS every team shows and each chip jumps to its section. */
[data-bz-section="team-directory"] .bz-block{padding-block:0}
[data-bz-section="team-directory"] .bz-btns{margin:0}
[data-bz-section="team-directory"] p:empty,[data-bz-section="team-directory"] a[href=""]{display:none}

/* Chips: six to a row, so Executive Staff + Florida sit on one line and South Carolina on the next. */
[data-bz-node="td-chips"]{display:grid;grid-template-columns:repeat(7,minmax(0,1fr));gap:10px}
[data-bz-node="td-chips"]>.bz-col{grid-column:auto;min-width:0}
[data-bz-node="td-chips"] .bz-btn{width:100%;justify-content:center;min-height:40px;padding:0 10px;font-size:.625rem;letter-spacing:.1em;border:1px solid #cfcfcb;border-radius:0;background:#fff;color:var(--ink);white-space:nowrap}
[data-bz-node="td-chips"] .bz-btn:hover{border-color:var(--ink)}
[data-bz-node="td-chips"] .bz-btn[data-active],[data-bz-node="td-chips"] .bz-btn.is-active{background:var(--ink);color:#fff;border-color:var(--ink)}
[data-bz-node="td-chips"] .bz-btn .td-n{margin-left:6px;opacity:.6}
[data-bz-node="td-meta"]{margin-top:var(--space-5);padding-top:var(--space-4);border-top:1px solid var(--line)}
[data-bz-node="td-count"] p{font:700 .6875rem/1.4 var(--font-body);letter-spacing:.16em;text-transform:uppercase;margin:0}
[data-bz-node="td-tag"] p{text-align:right;font-size:.875rem;color:#4a4945;margin:0}

/* Team sections */
.bz-section[data-bz-node^="td-group"]{padding-block:clamp(36px,4vw,56px)}
.bz-section[data-bz-node^="td-group"][hidden]{display:none!important}
[data-bz-node^="td-h"] h2{margin-bottom:var(--space-2)}
[data-bz-node^="td-intro"] p{font-size:.875rem;color:#4a4945;margin:0 0 var(--space-5)}
[data-bz-node^="td-cards"]{row-gap:var(--space-6)}
[data-bz-node^="td-photo"] .bz-container,[data-bz-node^="td-photo"] .bz-figure{max-width:none;padding:0;margin:0}
[data-bz-node^="td-photo"] img,[data-bz-node^="td-photo"] .bz-photo--empty{width:100%;aspect-ratio:4/5;object-fit:cover;object-position:top;display:block;border-radius:0}
/* No headshot yet: a neutral silhouette rather than the word "Photo". */
[data-bz-node^="td-photo"] .bz-photo--empty{color:transparent;font-size:0;background:radial-gradient(circle at 50% 38%,#cfcdc8 0 17%,transparent 17.5%),radial-gradient(ellipse at 50% 100%,#cfcdc8 0 38%,transparent 38.5%),#e4e2dd}
.bz-row[data-bz-node^="td-who"]{display:flex;justify-content:space-between;align-items:flex-start;gap:10px;margin-top:var(--space-3);padding-top:10px;border-top:2px solid var(--ink)}
.bz-row[data-bz-node^="td-who"]>.bz-col{grid-column:auto}
[data-bz-node^="td-who-txt"]{flex:1 1 auto;min-width:0}
[data-bz-node^="td-who-act"]{flex:0 0 auto}
[data-bz-node^="td-name"] h3{font:700 .8125rem/1.25 var(--font-heading);text-transform:uppercase;letter-spacing:.02em;margin:0 0 3px}
[data-bz-section="team-directory"] [data-bz-node^="td-role"] .bz-text p{font-size:.75rem;line-height:1.4;color:#4a4945;text-transform:uppercase;letter-spacing:.04em;margin:0}
[data-bz-node^="td-inv"] p{margin:0}
/* An empty link field renders as "#": no inventory or profile yet, so no link. */
[data-bz-node^="td-inv"] a[href="#"],[data-bz-node^="td-profile"] a[href="#"]{display:none}
[data-bz-node^="td-inv"] a{display:inline-block;padding:4px 7px;border-radius:3px;background:var(--accent);color:#151515;font:800 .5625rem/1 var(--font-body);letter-spacing:.08em;text-transform:uppercase;text-decoration:none;white-space:nowrap}
[data-bz-node^="td-inv"] a:hover{background:var(--ink);color:#fff}
[data-bz-node^="td-profile"] p{margin:8px 0 0}
[data-bz-node^="td-profile"] a{font:700 .625rem/1 var(--font-body);letter-spacing:.12em;text-transform:uppercase;color:var(--ink)}

@media (max-width:1100px){
  [data-bz-node="td-chips"]{grid-template-columns:repeat(4,minmax(0,1fr))}
  [data-bz-node^="td-cards"]>.bz-col{grid-column:span 4}
}
@media (max-width:640px){
  [data-bz-node="td-chips"]{grid-template-columns:repeat(2,minmax(0,1fr))}
  [data-bz-node^="td-cards"]>.bz-col{grid-column:span 6}
  [data-bz-node="td-tag"] p{text-align:left}
}

js:
/* Team directory filter. The platform `filter` behaviour matches on data- attributes that
   only widgets can emit, so the chips are links to each team's section (#team-miami) and this
   script turns them into filters: one team at a time, a live count, and a shareable address.
   Without it every team shows and each chip jumps to its section. */
(function () {
  document.querySelectorAll('[data-bz-section="team-directory"]').forEach(function (root) {
    var groups = [].slice.call(root.querySelectorAll('.bz-section[data-bz-node^="td-group"]'));
    var chips = [].slice.call(root.querySelectorAll('[data-bz-node="td-chips"] a'));
    var count = root.querySelector('[data-bz-node="td-count"] p');
    if (!groups.length || !chips.length) return;
    function keyOf(a) { return (a.getAttribute('href') || '').replace(/^#/, ''); }
    function size(g) { return g.querySelectorAll('[data-bz-node^="td-cards"] > .bz-col').length; }
    var total = groups.reduce(function (n, g) { return n + size(g); }, 0);
    chips.forEach(function (a) {
      var k = keyOf(a), g = groups.filter(function (x) { return x.id === k; })[0];
      var n = k === 'all' ? total : (g ? size(g) : 0);
      var s = document.createElement('span'); s.className = 'td-n'; s.textContent = n; a.appendChild(s);
      a.setAttribute('role', 'button');
    });
    function select(k, push) {
      var shown = 0;
      groups.forEach(function (g) { var on = k === 'all' || g.id === k; g.hidden = !on; if (on) shown += size(g); });
      chips.forEach(function (a) { var on = keyOf(a) === k; a.classList.toggle('is-active', on); a.setAttribute('aria-pressed', String(on)); });
      if (count) count.innerHTML = '<strong>Showing ' + shown + ' of ' + total + ' team members</strong>';
      if (push && history.replaceState) history.replaceState(null, '', k === 'all' ? location.pathname : '#' + k);
    }
    chips.forEach(function (a) {
      a.addEventListener('click', function (e) {
        e.preventDefault();
        var k = keyOf(a);
        select(a.classList.contains('is-active') && k !== 'all' ? 'all' : k, true);
      });
    });
    function fromHash() { var k = location.hash.replace(/^#/, ''); select(groups.some(function (g) { return g.id === k; }) ? k : 'all', false); }
    window.addEventListener('hashchange', fromHash);
    fromHash();
  });
})();
